import hashlib, json
from pathlib import Path
root = Path('products/services/accessible-document-paid-sample')
files = {'title_screen': ('boamp-title-screen.json', 'TASK-179512236111', '1a12538111218e5babe873c947bb49d656c95e0fbdf7ac5f41660f751a4d5911'), 'original_notice': ('boamp-26-109140.json', 'TASK-179512236112', '9df314799e4646882e7f5d8acb9874f2db4c8527a31529e8b9d6ce8fb1f477c2')}
evidence = {}
for name, (filename, receipt, expected_hash) in files.items():
    path = root / 'raw' / filename
    raw = path.read_bytes()
    actual_hash = hashlib.sha256(raw).hexdigest()
    if actual_hash != expected_hash:
        raise ValueError(f'Source hash mismatch for {path}')
    payload = json.loads(raw)
    rows = payload['results']
    evidence[name] = {'receipt': receipt, 'path': str(path), 'sha256': actual_hash, 'total_matches': payload['total_count'], 'returned_rows': len(rows)}
    if name == 'title_screen':
        evidence[name]['titles'] = [{key: row.get(key) for key in ('idweb', 'objet', 'dateparution')} for row in rows]
    else:
        if len(rows) != 1 or rows[0].get('idweb') != '26-109140':
            raise ValueError('Unexpected BOAMP notice identity')
        evidence[name]['idweb'] = rows[0]['idweb']
        evidence[name]['title'] = rows[0].get('objet')
report = {'scope': 'Source readback and title coverage for the existing accessibility procurement mission', 'sources': evidence, 'limitations': ['Titles are discovery leads only.', 'The original notice counts toward the existing inspection limit.', 'This readback establishes no supplier eligibility, accepted order or settlement.']}
output = root / 'boamp-source-readback.json'
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
